        public string? moneyWithCurrencyInEmailsFormat { get; set; }
    }

    ///<summary>
    ///A setting for a presentment currency.
    ///</summary>
    [Description("A setting for a presentment currency.")]
    public class CurrencySetting : GraphQLObject<CurrencySetting>
    {
        ///<summary>
        ///The currency&apos;s ISO code.
        ///</summary>
        [Description("The currency's ISO code.")]
        [NonNull]
        [EnumType(typeof(CurrencyCode))]
        public string? currencyCode { get; set; }

        ///<summary>
        ///The full name of the currency.
        ///</summary>
        [Description("The full name of the currency.")]
        [NonNull]
        public string? currencyName { get; set; }

        ///<summary>
        ///Whether the currency is enabled or not. An enabled currency setting is visible to buyers and allows orders to be generated with that currency as presentment.
        ///</summary>
        [Description("Whether the currency is enabled or not. An enabled currency setting is visible to buyers and allows orders to be generated with that currency as presentment.")]
        [NonNull]
        public bool? enabled { get; set; }

        ///<summary>
        ///The manual rate, if enabled, that applies to this currency when converting from shop currency. This rate is specific to the associated market&apos;s currency setting.
        ///</summary>
        [Description("The manual rate, if enabled, that applies to this currency when converting from shop currency. This rate is specific to the associated market's currency setting.")]
        public decimal? manualRate { get; set; }

        ///<summary>
        ///The date and time when the active exchange rate for the currency was last modified. It can be the automatic rate&apos;s creation date, or the manual rate&apos;s last updated at date if active.
        ///</summary>
        [Description("The date and time when the active exchange rate for the currency was last modified. It can be the automatic rate's creation date, or the manual rate's last updated at date if active.")]
        public DateTime? rateUpdatedAt { get; set; }
    }

