    ///<summary>
    ///Return type for `marketUpdate` mutation.
    ///</summary>
    [Description("Return type for `marketUpdate` mutation.")]
    public class MarketUpdatePayload : GraphQLObject<MarketUpdatePayload>
    {
        ///<summary>
        ///The market object.
        ///</summary>
        [Description("The market object.")]
        public Market? market { get; set; }

        ///<summary>
        ///The list of errors that occurred from executing the mutation.
        ///</summary>
        [Description("The list of errors that occurred from executing the mutation.")]
        [NonNull]
        public IEnumerable<MarketUserError>? userErrors { get; set; }
    }

    ///<summary>
    ///Defines errors encountered while managing a Market.
    ///</summary>
    [Description("Defines errors encountered while managing a Market.")]
    public class MarketUserError : GraphQLObject<MarketUserError>, IDisplayableError
    {
        ///<summary>
        ///The error code.
        ///</summary>
        [Description("The error code.")]
        [EnumType(typeof(MarketUserErrorCode))]
        public string? code { get; set; }

        ///<summary>
        ///The path to the input field that caused the error.
        ///</summary>
        [Description("The path to the input field that caused the error.")]
        public IEnumerable<string>? field { get; set; }

        ///<summary>
        ///The error message.
        ///</summary>
        [Description("The error message.")]
        [NonNull]
        public string? message { get; set; }
    }

