        [Description("The order associated with the refund.")]
        [NonNull]
        public Order? order { get; set; }

        ///<summary>
        ///The order adjustments that are attached with the refund.
        ///</summary>
        [Description("The order adjustments that are attached with the refund.")]
        [NonNull]
        public OrderAdjustmentConnection? orderAdjustments { get; set; }

        ///<summary>
        ///The `RefundLineItem` resources attached to the refund.
