        ///</summary>
        [Description("Payment method is invalid. Please update or create a new payment method.")]
        INVALID_PAYMENT_METHOD,
        ///<summary>
        ///There was an unexpected error during the billing attempt.
        ///</summary>
        [Description("There was an unexpected error during the billing attempt.")]
        UNEXPECTED_ERROR,
        ///<summary>
        ///Payment method is expired.
        ///</summary>
        [Description("Payment method is expired.")]
        EXPIRED_PAYMENT_METHOD,
        ///<summary>
        ///Payment method was declined by processor.
        ///</summary>
        [Description("Payment method was declined by processor.")]
        PAYMENT_METHOD_DECLINED,
        ///<summary>
        ///There was an error during the authentication.
        ///</summary>
        [Description("There was an error during the authentication.")]
        AUTHENTICATION_ERROR,
        ///<summary>
        ///Gateway is in test mode and attempted to bill a live payment method.
        ///</summary>
        [Description("Gateway is in test mode and attempted to bill a live payment method.")]
        TEST_MODE,
        ///<summary>
        ///Payment method was canceled by buyer.
        ///</summary>
        [Description("Payment method was canceled by buyer.")]
        BUYER_CANCELED_PAYMENT_METHOD,
        ///<summary>
        ///Customer was not found.
        ///</summary>
        [Description("Customer was not found.")]
        CUSTOMER_NOT_FOUND,
        ///<summary>
        ///Customer is invalid.
        ///</summary>
        [Description("Customer is invalid.")]
        CUSTOMER_INVALID,
        ///<summary>
        ///The shipping address is either missing or invalid.
        ///</summary>
        [Description("The shipping address is either missing or invalid.")]
        INVALID_SHIPPING_ADDRESS,
        ///<summary>
        ///The billing agreement ID or the transaction ID for the customer&apos;s payment method is invalid.
        ///</summary>
        [Description("The billing agreement ID or the transaction ID for the customer's payment method is invalid.")]
        INVALID_CUSTOMER_BILLING_AGREEMENT,
        ///<summary>
        ///A payment has already been made for this invoice.
        ///</summary>
        [Description("A payment has already been made for this invoice.")]
        INVOICE_ALREADY_PAID,
        ///<summary>
        ///Payment method cannot be used with the current payment gateway test mode configuration.
        ///</summary>
        [Description("Payment method cannot be used with the current payment gateway test mode configuration.")]
        PAYMENT_METHOD_INCOMPATIBLE_WITH_GATEWAY_CONFIG,
        ///<summary>
        ///The amount is too small.
        ///</summary>
        [Description("The amount is too small.")]
        AMOUNT_TOO_SMALL,
        ///<summary>
        ///No inventory location found or enabled.
        ///</summary>
        [Description("No inventory location found or enabled.")]
        INVENTORY_ALLOCATIONS_NOT_FOUND,
        ///<summary>
        ///Not enough inventory found.
        ///</summary>
        [Description("Not enough inventory found.")]
        INSUFFICIENT_INVENTORY,
        ///<summary>
        ///Transient error, try again later.
        ///</summary>
        [Description("Transient error, try again later.")]
        TRANSIENT_ERROR,
        ///<summary>
        ///Insufficient funds.
        ///</summary>
        [Description("Insufficient funds.")]
        INSUFFICIENT_FUNDS,
        ///<summary>
        ///Purchase Type is not supported.
        ///</summary>
        [Description("Purchase Type is not supported.")]
        PURCHASE_TYPE_NOT_SUPPORTED,
        ///<summary>
        ///Paypal Error General.
        ///</summary>
        [Description("Paypal Error General.")]
        PAYPAL_ERROR_GENERAL,
        ///<summary>
        ///Card number was incorrect.
        ///</summary>
        [Description("Card number was incorrect.")]
        CARD_NUMBER_INCORRECT,
        ///<summary>
        ///Fraud was suspected.
        ///</summary>
        [Description("Fraud was suspected.")]
        FRAUD_SUSPECTED,
        ///<summary>
        ///Non-test order limit reached. Use a test payment gateway to place another order.
        ///</summary>
        [Description("Non-test order limit reached. Use a test payment gateway to place another order.")]
        NON_TEST_ORDER_LIMIT_REACHED,
        ///<summary>
        ///Gift cards must have a price greater than zero.
        ///</summary>
        [Description("Gift cards must have a price greater than zero.")]
        FREE_GIFT_CARD_NOT_ALLOWED,
        ///<summary>
        ///Payment method is not specified on subscription contract.
        ///</summary>
        [Description("Payment method is not specified on subscription contract.")]
        PAYMENT_METHOD_NOT_SPECIFIED,
    }

